SELECT store_id, CASE WHEN YEAR(last_restock) < 2024 THEN 'before_2024' WHEN YEAR(last_restock) = 2024 THEN '2024' ELSE 'after_2024' END AS last_restock_cohort, MIN(last_restock) AS first_last_restock, ROUND(AVG(quantity), 2) AS avg_quantity, MIN(quantity) AS min_quantity FROM inventory GROUP BY store_id, CASE WHEN YEAR(last_restock) < 2024 THEN 'before_2024' WHEN YEAR(last_restock) = 2024 THEN '2024' ELSE 'after_2024' END
